# test_contract.py; synthetic teaching example, shown and not executed in this build.
import pytest
from fastapi.testclient import TestClient
import server

class FakeClaims:
    def __init__(self):
        self.rows = {}
    def claim(self, key, revision, reviewer):
        holder = self.rows.setdefault((key, revision), reviewer)
        if holder != reviewer:
            return {"status": "conflict", "claimed_by": holder}
        return {"status": "claimed"}

@pytest.fixture
def client():
    server.deps.claims = FakeClaims()
    server.deps.plants_of = lambda r: {"P1"} if r == "tomas.b" else {"P2"}
    server.deps.plant_of_item = lambda key: "P2"
    return TestClient(server.app)

def as_(name):
    return {"X-Forwarded-Email": f"{name}@cinderline.example"}

BODY = {"inspection_key": "A-2031", "revision": 2}

def test_claim_then_conflict(client):
    assert client.post("/v1/claims", json=BODY, headers=as_("imani.q")).json() == {"status": "claimed"}
    assert client.post("/v1/claims", json=BODY, headers=as_("leo.d")).json() == {
        "status": "conflict", "claimed_by": "imani.q"}

def test_injected_key_refused_before_any_write(client):
    bad = {"inspection_key": "A-2031' OR '1'='1", "revision": 2}
    r = client.post("/v1/claims", json=bad, headers=as_("imani.q"))
    assert r.status_code == 422 and r.json()["detail"][0]["loc"] == ["body", "inspection_key"]
    assert server.deps.claims.rows == {}

def test_other_plant_refused(client):
    r = client.post("/v1/claims", json=BODY, headers=as_("tomas.b"))
    assert r.status_code == 403 and r.json()["detail"]["reason"] == "plant"

def test_body_cannot_name_another_reviewer(client):
    r = client.post("/v1/claims", json={**BODY, "reviewer": "leo.d"}, headers=as_("imani.q"))
    assert r.status_code == 403 and r.json()["detail"]["reason"] == "reviewer"

def test_missing_identity_header(client):
    assert client.post("/v1/claims", json=BODY).status_code == 401
```

**Record what each fake replaced:** `FakeClaims` replaced Lakebase and its one-claim constraint; the lambdas replaced the plant roster; the hand-set header replaced the platform's sign-in. Each replacement is an open item for a deployment check, and the review note lists them.
